insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g3_ela_v1'
from (values
('110.5.b.3.A',3,'A dictionary entry for "tide" lists two meanings. The sentence is "The tide came in at noon." Which meaning fits?','["the rise and fall of the sea", "a kind of soap", "a large crowd", "a short race"]'::jsonb,0,'The sentence is about water at the shore.','original'),
('110.5.b.3.A',3,'Which tool shows how to divide a word into syllables and say it?','["a map key", "a dictionary entry", "a calendar", "a table of contents"]'::jsonb,1,'Dictionaries show syllables and pronunciation.','original'),
('110.5.b.3.B',3,'"The detective examined the footprints carefully and noticed a pattern." What does examined mean?','["sang about", "painted over", "looked at closely", "threw away"]'::jsonb,2,'Context says carefully and noticed.','original'),
('110.5.b.3.B',3,'"The ice cream was so delicious that I devoured it in seconds." What does devoured mean?','["dropped", "froze", "saved", "ate quickly"]'::jsonb,3,'The clues say in seconds.','original'),
('110.5.b.3.B',4,'"The old bridge was fragile, so the town closed it before it could collapse." What does fragile mean?','["easily broken", "painted blue", "very long", "brand new"]'::jsonb,0,'Closing it before it collapses shows weakness.','original'),
('110.5.b.3.C',3,'What does the prefix mis- mean in "misplace"?','["full of", "wrongly", "before", "again"]'::jsonb,1,'Mis- means wrongly or badly.','original'),
('110.5.b.3.C',3,'What does the suffix -able mean in "washable"?','["before", "again", "can be done", "without"]'::jsonb,2,'-able means able to be.','original'),
('110.5.b.3.C',3,'Which word means "to fill again"?','["misfill", "unfill", "prefill", "refill"]'::jsonb,3,'Re- means again.','original'),
('110.5.b.3.D',3,'Which word is a synonym for "difficult"?','["hard", "simple", "easy", "light"]'::jsonb,0,'Hard means about the same as difficult.','original'),
('110.5.b.3.D',3,'Which pair are antonyms?','["happy, glad", "brave, fearful", "quick, fast", "big, large"]'::jsonb,1,'Brave and fearful are opposites.','original'),
('110.5.b.3.D',3,'Which words are homophones?','["bear, beer", "cat, cap", "knight, night", "ship, sheep"]'::jsonb,2,'Knight and night sound the same.','original'),
('110.5.b.3.D',4,'"The pitcher poured water" and "The pitcher threw the ball" show that pitcher is a...','["compound word", "prefix", "contraction", "multiple-meaning word"]'::jsonb,3,'One word has two meanings.','original'),
('110.5.b.3.D',4,'"It''s raining cats and dogs." This phrase is an example of...','["an idiom", "a fact", "a prefix", "a rhyme"]'::jsonb,0,'An idiom does not mean its exact words.','original'),
('110.5.b.6.A',2,'A student reads a recipe book before baking. What is the purpose?','["to hear a poem", "to follow directions", "to learn math facts", "to find a pet"]'::jsonb,1,'A recipe gives directions.','original'),
('110.5.b.6.B',3,'Which question could a student ask before reading an article about glaciers?','["Where is my shoe?", "Who won the game?", "How do glaciers form?", "What time is lunch?"]'::jsonb,2,'It fits the topic.','original'),
('110.5.b.6.C',3,'A story begins with dark clouds and strong wind. What might happen next?','["a picnic", "a parade", "a nap", "a storm"]'::jsonb,3,'The clues point to a storm.','original'),
('110.5.b.6.D',3,'"The classroom buzzed like a hive of bees." What do you picture?','["a noisy busy room", "a quiet library", "an empty hall", "a dark cave"]'::jsonb,0,'The simile shows noisy activity.','original'),
('110.5.b.6.E',3,'A story about a family moving reminds you of a friend who moved. This is a...','["summary", "connection to your experience", "rhyme", "prediction"]'::jsonb,1,'You linked it to your life.','original'),
('110.5.b.6.F',3,'Marco''s backpack is soaked and his hair is dripping. What can you infer?','["he took a nap", "he is cold from ice cream", "he was caught in the rain", "he baked bread"]'::jsonb,2,'The clues point to rain.','original'),
('110.5.b.6.G',3,'Read: "Honeybees visit flowers to collect nectar. In doing so, they carry pollen from plant to plant." What is the key idea?','["bees are black and yellow", "honey is sweet", "flowers are pretty", "bees help plants make seeds"]'::jsonb,3,'The key point is pollination.','original'),
('110.5.b.6.H',3,'Text 1 says plants need sunlight. Text 2 says plants need water. What can you conclude?','["plants need more than one thing to grow", "plants only need soil", "sun harms plants", "plants need no care"]'::jsonb,0,'Combine the facts.','original'),
('110.5.b.6.I',3,'You get to the end of a page and cannot explain what happened. What is the best step?','["close your eyes", "reread the page", "go to the next book", "erase the page"]'::jsonb,1,'Rereading helps comprehension.','original'),
('110.5.b.7.A',3,'A student says, "This story reminds me of the book we read about friendship." This is a connection to...','["a weather report", "a math problem", "another text", "a recipe"]'::jsonb,2,'It links to another book.','original'),
('110.5.b.7.B',3,'Which response to a story uses evidence?','["Rosa is a name.", "I liked it.", "It was long.", "I think Rosa is brave because she faced the dog."]'::jsonb,3,'It gives an opinion with a reason.','original'),
('110.5.b.7.C',3,'Which detail from the text best supports "Ben was nervous"?','["His hands shook as he walked to the stage.", "The stage was wooden.", "Ben wore a blue shirt.", "There were chairs."]'::jsonb,0,'Shaking hands show nerves.','original'),
('110.5.b.7.D',3,'Which is the best paraphrase of "The dense fog made driving dangerous"?','["The road was dry.", "Thick fog made it risky to drive.", "Cars are fast.", "Fog is white."]'::jsonb,1,'A paraphrase uses new words with the same meaning.','original'),
('110.5.b.7.E',3,'While reading about volcanoes, a student writes short notes. This is...','["illustrating a menu", "a fable", "notetaking", "rhyming"]'::jsonb,2,'Notes capture key ideas.','original'),
('110.5.b.7.F',3,'A student reads the word "habitat" in science and then uses it in a sentence. Which is correct?','["Habitat is a color.", "A frog is a habitat.", "Habitat runs fast.", "A frog''s habitat is a pond."]'::jsonb,3,'The sentence uses habitat correctly.','original'),
('110.5.b.8.A',3,'A story shows a boy sharing his lunch with a hungry friend. What theme does it teach?','["kindness matters", "lunch is cold", "school is long", "friends are loud"]'::jsonb,0,'The theme is a lesson.','original'),
('110.5.b.8.A',4,'How is a theme different from a topic?','["a topic is a message", "a theme is a message; a topic is what the text is about", "they mean the same thing", "a theme is a place"]'::jsonb,1,'A theme is a lesson; a topic is the subject.','original'),
('110.5.b.8.B',3,'In a story, a main character wants to win a race, but her friend wants to help her train. How are they connected?','["the friend is the plot", "the friend is the setting", "the friend supports the main character", "the friend is the title"]'::jsonb,2,'Characters can help each other.','original'),
('110.5.b.8.B',4,'Which is a minor character?','["the character who solves the problem", "the hero of the story", "the narrator who tells the whole tale", "a store clerk who appears once"]'::jsonb,3,'Minor characters appear briefly.','original'),
('110.5.b.8.C',3,'In a plot, the high point of the action is called the...','["climax", "title", "moral", "setting"]'::jsonb,0,'The climax is the turning point.','original'),
('110.5.b.8.C',3,'What happens in the resolution of a story?','["the characters are introduced", "the problem is solved", "the title is shown", "the setting is described"]'::jsonb,1,'The resolution resolves the problem.','original'),
('110.5.b.8.D',3,'A story takes place in a lonely lighthouse during a storm. How does this setting influence the plot?','["it removes the characters", "it makes the plot shorter", "it creates danger and suspense", "it changes the author"]'::jsonb,2,'The setting affects events.','original'),
('110.5.b.9.A',3,'Which genre often has talking animals and ends with a lesson?','["newspaper article", "science report", "biography", "fable"]'::jsonb,3,'Fables teach morals.','original'),
('110.5.b.9.A',3,'A story about real events in a person''s life, written by someone else, is a...','["biography", "play", "myth", "fable"]'::jsonb,0,'A biography tells about a life.','original'),
('110.5.b.9.A',3,'A traditional story that explains how something in nature came to be is a...','["schedule", "myth", "map", "recipe"]'::jsonb,1,'Myths explain natural events.','original'),
('110.5.b.9.B',3,'In the poem lines "The cat sat on the mat / and wore a funny hat," which words rhyme?','["sat and wore", "cat and funny", "mat and hat", "on and wore"]'::jsonb,2,'Mat and hat end alike.','original'),
('110.5.b.9.B',3,'A poem repeats the same beginning sound in "wild waves wash." This sound device is...','["rhyme", "dialogue", "setting", "alliteration"]'::jsonb,3,'Repeating first sounds is alliteration.','original'),
('110.5.b.9.B',3,'The word "buzz" imitates a sound. This is called...','["onomatopoeia", "metaphor", "summary", "prefix"]'::jsonb,0,'Onomatopoeia imitates sounds.','original'),
('110.5.b.9.C',3,'In a play, directions in parentheses that tell actors how to move are called...','["titles", "stage directions", "chapters", "glossary"]'::jsonb,1,'Stage directions guide actors.','original'),
('110.5.b.9.C',3,'In a drama, the lines that characters speak are...','["plot", "rhyme", "dialogue", "setting"]'::jsonb,2,'Dialogue is spoken lines.','original'),
('110.5.b.9.D.i',3,'A passage describes how octopuses use camouflage, ink, and speed to escape predators. What is the central idea?','["fish swim", "oceans are big", "octopuses are red", "octopuses have ways to stay safe"]'::jsonb,3,'The details show safety methods.','original'),
('110.5.b.9.D.ii',3,'Which text feature would show how a river''s depth changed each month?','["a graph", "a title page", "a glossary", "a cover"]'::jsonb,0,'Graphs show data.','original'),
('110.5.b.9.D.ii',3,'A bulleted list in an article is used to...','["replace the title", "show items clearly", "hide information", "add rhymes"]'::jsonb,1,'Bullets list items.','original'),
('110.5.b.9.D.iii',3,'"Because the dam broke, the town flooded." This sentence uses which pattern?','["dialogue", "compare and contrast", "cause and effect", "rhyme"]'::jsonb,2,'Because shows a cause.','original'),
('110.5.b.9.D.iii',3,'An article describes a problem with litter and then gives solutions. The structure is...','["poetry", "rhyme", "chronological order", "problem and solution"]'::jsonb,3,'It poses a problem then answers it.','original'),
('110.5.b.9.E.i',3,'An author writes, "Gardens teach students about plants, so every school needs one." What is the claim?','["every school needs a garden", "students like recess", "plants need water", "gardens have flowers"]'::jsonb,0,'The claim is the main opinion.','original'),
('110.5.b.9.E.iii',3,'A pamphlet about how to ride a bike safely is meant for...','["pilots", "new riders", "chefs", "astronauts"]'::jsonb,1,'The audience is people who ride.','original'),
('110.5.b.9.F',3,'Which is a feature of a multimodal text?','["it has only numbers", "it has no pictures", "it combines words, images, and sound", "it has only words"]'::jsonb,2,'Multimodal means more than one mode.','original'),
('110.5.b.10.A',3,'An author writes an article titled "Why We Should Protect Sea Turtles." What is the author''s purpose?','["to entertain only", "to measure", "to confuse", "to persuade"]'::jsonb,3,'The title argues for a cause.','original'),
('110.5.b.10.A',4,'What message might an author share in a story about a girl who keeps practicing until she wins?','["hard work pays off", "practice is boring", "winning is luck", "girls run slowly"]'::jsonb,0,'The message is about perseverance.','original'),
('110.5.b.10.B',3,'An author lists events in the order they happened. Why?','["to hide the ending", "so the reader can follow the sequence", "to make it short", "to add rhyme"]'::jsonb,1,'Time order helps the reader follow.','original'),
('110.5.b.10.C',3,'Why does an author put a word in italics?','["to end the page", "to hide the word", "to show emphasis", "to make it a rhyme"]'::jsonb,2,'Italics show stress.','original'),
('110.5.b.10.D',3,'"The moon was a silver coin in the sky." This is an example of...','["a fact", "a prefix", "a date", "a metaphor"]'::jsonb,3,'It compares the moon to a coin without like or as.','original'),
('110.5.b.10.D',3,'"She runs like the wind." This is an example of...','["a simile", "a metaphor", "a fact", "a rhyme"]'::jsonb,0,'A simile uses like or as.','original'),
('110.5.b.10.E',3,'A story is told by a character using "I" and "my." This is...','["a summary", "first-person point of view", "third-person point of view", "second person"]'::jsonb,1,'First-person uses I.','original'),
('110.5.b.10.F',3,'Which phrase shows the author''s voice as playful?','["They were there.", "Goats are animals.", "Gigantic garbage-gobbling goats gulped greedily!", "The goats ate."]'::jsonb,2,'Playful word choice shows voice.','original'),
('110.5.b.10.G',3,'"I''ve told you a million times to clean your room!" is an example of...','["a fact", "a metaphor", "a rhyme", "hyperbole"]'::jsonb,3,'Hyperbole exaggerates.','original'),
('110.5.b.10.G',3,'Which sentence uses hyperbole?','["I''m so hungry I could eat a horse.", "Lunch is at noon.", "I like soup.", "I ate a sandwich."]'::jsonb,0,'It exaggerates hunger.','original'),
('110.5.b.11.B.i',3,'Which is the best introductory sentence for an essay about recycling?','["I ate lunch.", "Recycling helps keep our planet clean.", "The end.", "Plastic."]'::jsonb,1,'An introduction states the topic.','original'),
('110.5.b.11.B.ii',3,'Which detail supports an idea about exercise being healthy?','["Shoes are comfy.", "Bananas are yellow.", "Running makes your heart strong.", "The sky is blue."]'::jsonb,2,'It supports the idea.','original'),
('110.5.b.11.C',3,'Which revision combines two short sentences into a better one? "I like soccer. I like tennis."','["Soccer tennis like.", "I like I like.", "Like soccer.", "I like soccer and tennis."]'::jsonb,3,'And joins the ideas.','original'),
('110.5.b.11.C',3,'Which word is a stronger choice than "said" in "I''m so tired," said Ava?','["sighed", "did", "went", "put"]'::jsonb,0,'Sighed shows how she spoke.','original'),
('110.5.b.11.D.i',3,'Which is a compound sentence?','["Running quickly home.", "I wanted pizza, but we ate soup.", "I wanted pizza.", "Pizza with cheese."]'::jsonb,1,'A compound sentence joins two complete ideas.','original'),
('110.5.b.11.D.ii',3,'Which sentence is written in the future tense?','["The bus had arrived.", "The bus arrives at eight.", "The bus will arrive at eight.", "The bus arrived at eight."]'::jsonb,2,'Will arrive is future.','original'),
('110.5.b.11.D.iii',3,'Which sentence has a proper noun?','["We saw a boat.", "We visited a lake.", "We swam in water.", "We visited Lake Travis."]'::jsonb,3,'Lake Travis names a specific place.','original'),
('110.5.b.11.D.iv',3,'Which word is the superlative form of "tall"?','["tallest", "more tall", "taller", "tallish"]'::jsonb,0,'Superlative compares three or more.','original'),
('110.5.b.11.D.iv',3,'Which is the comparative form of "fast"?','["most fast", "faster", "fastly", "fastest"]'::jsonb,1,'Comparative compares two.','original'),
('110.5.b.11.D.v',3,'Which word is an adverb of manner?','["yesterday", "never", "quietly", "tomorrow"]'::jsonb,2,'Quietly tells how.','original'),
('110.5.b.11.D.vi',3,'Which sentence has a prepositional phrase?','["The cat purred.", "The cat slept.", "The sleepy cat yawned.", "The cat slept on the couch."]'::jsonb,3,'On the couch is a prepositional phrase.','original'),
('110.5.b.11.D.vii',3,'Which pronoun completes the sentence? "Please give the book to ___."','["her", "hers''s", "she", "they''re"]'::jsonb,0,'Her is the object pronoun.','original'),
('110.5.b.11.D.viii',3,'Which sentence uses a coordinating conjunction correctly?','["But I wanted to go it rained.", "I wanted to go, but it rained.", "I wanted but to go.", "I wanted to go but, it rained."]'::jsonb,1,'A comma comes before but in a compound sentence.','original'),
('110.5.b.11.D.ix',3,'Which of these words should always start with a capital letter?','["dinner", "table", "Thanksgiving", "turkey"]'::jsonb,2,'Names of holidays are capitalized.','original'),
('110.5.b.11.D.ix',3,'Which name includes an official title that needs a capital letter?','["the doctor", "my teacher", "a mayor", "Governor Ortiz"]'::jsonb,3,'An official title before a name is capitalized.','original'),
('110.5.b.11.D.x',3,'Which sentence uses an apostrophe correctly?','["That is Ana''s backpack.", "That is Anas'' backpack.", "That is Anas backpack''.", "That is Ana,s backpack."]'::jsonb,0,'An apostrophe plus s shows possession.','original'),
('110.5.b.11.D.x',3,'Which sentence uses commas correctly?','["On Monday we, went to the zoo.", "On Monday, we went to the zoo.", "On Monday we went, to the zoo.", "On, Monday we went to the zoo."]'::jsonb,1,'A comma follows an introductory phrase.','original'),
('110.5.b.11.D.x',3,'Which sentence has quotation marks correct?','["\"I am ready, said Eli.\"", "I am ready, \"said Eli.\"", "\"I am ready,\" said Eli.", "\"I am ready said Eli.\""]'::jsonb,2,'Quotation marks surround only the spoken words.','original'),
('110.5.b.12.A',3,'What belongs in the beginning of a personal narrative?','["only the ending", "a table", "a list of facts", "who, where, and when the story takes place"]'::jsonb,3,'The beginning sets the scene.','original'),
('110.5.b.12.B',3,'A brief informational composition about frogs should begin with...','["a sentence that names the topic", "a joke", "an unrelated story", "the last fact"]'::jsonb,0,'The introduction names the topic.','original'),
('110.5.b.12.C',3,'An opinion essay should include...','["a recipe", "a claim and reasons", "only facts without an idea", "only a rhyme"]'::jsonb,1,'A claim needs reasons.','original'),
('110.5.b.12.C',3,'Which sentence is a strong closing for an opinion essay about recess?','["I like cake.", "Then it rained.", "For these reasons, recess is important for students.", "The end."]'::jsonb,2,'A conclusion restates the claim.','original'),
('110.5.b.12.D',3,'The closing of a friendly letter might be...','["Thank you", "Dear Sam", "Hello", "Your friend, Sam"]'::jsonb,3,'A closing comes at the end before the name.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
